package pages;

import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.PageFactory;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import utilities.WaitUtils;

import java.time.Duration;
import java.util.List;

public class TransferPage {

    private final WebDriver driver;
    private final WebDriverWait wait;

    public TransferPage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        PageFactory.initElements(driver, this);
    }

    @FindBy(xpath = "(//span[normalize-space()='Select account'])[1]")
    private WebElement fromAccountDropdown;

    @FindBy(xpath = "(//span[normalize-space()='Select account'])[2]")
    private WebElement toAccountDropdown;

    @FindBy(id = "transfer-amount")
    private WebElement amountTextbox;

    @FindBy(xpath = "//button[normalize-space()='Review Transfer']")
    private WebElement reviewTransferButton;

    @FindBy(xpath = "//button[normalize-space()='Confirm Transfer']")
    private WebElement confirmTransferButton;

    @FindBy(xpath = "//h1[contains(normalize-space(),'Transfer Successful')]")
    private WebElement transferSuccessfulMessageText;


    public void selectFromAccount(String accountName) {

        wait.until(
                ExpectedConditions.elementToBeClickable(fromAccountDropdown)
        ).click();

        selectAccountOption(accountName);
    }


    public void selectToAccount(String accountName) {

        wait.until(
                ExpectedConditions.elementToBeClickable(toAccountDropdown)
        ).click();

        selectAccountOption(accountName);
    }


    private void selectAccountOption(String accountName) {

        /*
         * The dropdown displays:
         *
         * Everyday Checking — $4,240.00
         * High-Yield Savings — $12,810.00
         * Pipeline — $10.00
         *
         * Therefore we match the account name at the beginning
         * of the option text instead of matching the complete text.
         */
        By accountOption = By.xpath(
                "//*[contains(normalize-space(text()),'" + accountName + "')]"
        );

        List<WebElement> options = wait.until(
                ExpectedConditions.visibilityOfAllElementsLocatedBy(
                        accountOption
                )
        );

        for (WebElement option : options) {

            if (option.isDisplayed()) {

                wait.until(
                        ExpectedConditions.elementToBeClickable(option)
                );

                option.click();

                return;
            }
        }

        throw new RuntimeException(
                "Unable to select account: " + accountName
        );
    }


    public void enterAmount(String amount) {

        WebElement amountField = wait.until(
                ExpectedConditions.visibilityOf(amountTextbox)
        );

        amountField.clear();
        amountField.sendKeys(amount);
    }


    public void clickOnReviewTransferButton() {

        wait.until(
                ExpectedConditions.elementToBeClickable(
                        reviewTransferButton
                )
        ).click();
    }


    public void clickOnConfirmTransferButton() {

        wait.until(
                ExpectedConditions.elementToBeClickable(
                        confirmTransferButton
                )
        ).click();
    }


    public String getTransferSuccessfulMessageText() {

        return wait.until(
                ExpectedConditions.visibilityOf(
                        transferSuccessfulMessageText
                )
        ).getText();
    }
}

package pages;

import org.openqa.selenium.By;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.NoSuchElementException;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.FindBy;
import org.openqa.selenium.support.PageFactory;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import utilities.WaitUtils;

import java.time.Duration;
import java.util.List;

public class TransferPage {

    private final WebDriver driver;
    private final WebDriverWait wait;
    private final By accountDropdownButtons = By.cssSelector("button[id*='headlessui-listbox-button']");

    public TransferPage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(10));
        PageFactory.initElements(driver, this);
    }

    @FindBy(id = "transfer-amount")
    private WebElement amountTextbox;

    @FindBy(xpath = "//button[normalize-space()='Review Transfer']")
    private WebElement reviewTransferButton;

    @FindBy(xpath = "//button[normalize-space()='Confirm Transfer']")
    private WebElement confirmTransferButton;

    @FindBy(xpath = "//h1[contains(normalize-space(),'Transfer Successful')]")
    private WebElement transferSuccessfulMessageText;


    public void selectFromAccount(String accountName) {
        openAccountDropdownByIndex(0);
        selectAccountOption(accountName);
    }


    public void selectToAccount(String accountName) {
        openAccountDropdownByIndex(1);
        selectAccountOption(accountName);
    }


    private void openAccountDropdownByIndex(int index) {

        wait.until(
                ExpectedConditions.numberOfElementsToBeMoreThan(
                        accountDropdownButtons,
                        index
                )
        );

        List<WebElement> dropdownButtons = driver.findElements(accountDropdownButtons);
        WebElement dropdownButton = dropdownButtons.get(index);

        wait.until(
                ExpectedConditions.elementToBeClickable(dropdownButton)
        );

        ((JavascriptExecutor) driver).executeScript(
                "arguments[0].click();",
                dropdownButton
        );
    }


    private void selectAccountOption(String accountName) {

        /*
         * The dropdown displays:
         *
         * Everyday Checking — $4,240.00
         * High-Yield Savings — $12,810.00
         * Pipeline — $10.00
         *
         * Therefore we match the account name at the beginning
         * of the option text instead of matching the complete text.
         */
        By accountOption = By.xpath(
                "//*[contains(normalize-space(.),'" + accountName + "')]"
        );

        List<WebElement> options = wait.until(
                ExpectedConditions.visibilityOfAllElementsLocatedBy(
                        accountOption
                )
        );

        for (WebElement option : options) {

            if (option.isDisplayed()) {

                ((JavascriptExecutor) driver).executeScript(
                        "arguments[0].click();",
                        option
                );

                return;
            }
        }

        throw new NoSuchElementException(
                "Unable to select account: " + accountName
        );
    }


    public void enterAmount(String amount) {

        WebElement amountField = wait.until(
                ExpectedConditions.visibilityOf(amountTextbox)
        );

        amountField.clear();
        amountField.sendKeys(amount);
    }


    public void clickOnReviewTransferButton() {

        wait.until(
                ExpectedConditions.elementToBeClickable(
                        reviewTransferButton
                )
        ).click();
    }


    public void clickOnConfirmTransferButton() {

        wait.until(
                ExpectedConditions.elementToBeClickable(
                        confirmTransferButton
                )
        ).click();
    }


    public String getTransferSuccessfulMessageText() {

        return wait.until(
                ExpectedConditions.visibilityOf(
                        transferSuccessfulMessageText
                )
        ).getText();
    }
}
